#!/usr/bin/env python3
"""Generate Vulkan 1.1 grouped AdamW shaders with fixed descriptor layouts."""
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1] / "csrc" / "shaders"
def emit(amsgrad, width):
    out = [
        "#version 450",
        "// Generated by scripts/generate_adamw_multitensor.py; do not edit.",
        "layout(local_size_x = 256) in;",
    ]
    names = ["param", "grad", "moment1", "moment2"] + (["maximum"] if amsgrad else [])
    for lane in range(width):
        for j, name in enumerate(names):
            readonly = "readonly " if name == "grad" else ""
            out.append(
                f"layout(set=0,binding={lane*len(names)+j}) {readonly}"
                f"buffer State_{name}_{lane} {{ float data[]; }} {name}{lane};"
            )
    fields = ["float lr;", "float beta1;", "float beta2;",
              "float eps;", "float weight_decay;"]
    fields += [f"uint end{lane};" for lane in range(width)]
    for prefix in ("bc1", "bc2"):
        fields += [f"float {prefix}{lane};" for lane in range(width)]
    out += ["layout(push_constant) uniform Args {"] + ["    " + f for f in fields] + ["} args;"]
    for lane in range(width):
        first = f"args.end{lane-1}" if lane else "0u"
        out += [
            f"void update{lane}(uint wg) {{",
            f"  uint i = (wg - {first}) * 256u + gl_LocalInvocationID.x;",
            f"  if (i >= uint(param{lane}.data.length())) return;",
            f"  float g = grad{lane}.data[i];",
            f"  float m = args.beta1 * moment1{lane}.data[i] + (1.0 - args.beta1) * g;",
            f"  float v = args.beta2 * moment2{lane}.data[i] + (1.0 - args.beta2) * g * g;",
            f"  moment1{lane}.data[i] = m;",
            f"  moment2{lane}.data[i] = v;",
        ]
        if amsgrad:
            out += [
                f"  float oldmax = maximum{lane}.data[i];",
                "  float maxv = (isnan(oldmax) || isnan(v)) ?",
                "      uintBitsToFloat(0x7fc00000u) : max(oldmax, v);",
                f"  maximum{lane}.data[i] = maxv;",
                f"  float denominator = sqrt(maxv / args.bc2{lane}) + args.eps;",
            ]
        else:
            out.append(f"  float denominator = sqrt(v / args.bc2{lane}) + args.eps;")
        out += [
            f"  float decayed_p = param{lane}.data[i] * (1.0 - args.lr * args.weight_decay);",
            f"  param{lane}.data[i] = decayed_p - (args.lr / args.bc1{lane}) * m / denominator;",
            "}",
        ]
    out.append("void main() {")
    out.append("    uint wg = gl_WorkGroupID.x;")
    for lane in range(width):
        keyword = "if" if lane == 0 else "else if"
        out.append(f"    {keyword} (wg < args.end{lane}) update{lane}(wg);")
    out.append("}")
    return "\n".join(out) + "\n"

def main():
    for width in (4,8):
        for amsgrad in (False, True):
            name = f"adamw_multitensor{width}" + ("_amsgrad.comp" if amsgrad else ".comp")
            target = ROOT / name
            target.write_text(emit(amsgrad,width))
            print(target)

if __name__ == "__main__":
    main()
